<script>
  import { onMount } from "svelte";
  import Dialogs, { askConfirm } from "./components/Dialogs.svelte";
  import SystemSurface from "../../ui-schema/views/SystemSurface.svelte";
  let users=[],invites=[],loading=true,error="",tab="users",showCreateUser=false,editing=null,savingUser=false,deletingUserId="",inviteCode="",creatingInvite=false,revokingCode="",userPage=1;
  const usersPerPage=10;
  function userPageCount(){return Math.max(1,Math.ceil(users.length/usersPerPage))} function pagedUsers(){const start=(userPage-1)*usersPerPage;return users.slice(start,start+usersPerPage)} function setUserPage(page){userPage=Math.min(Math.max(1,page),userPageCount())}
  let editForm={name:"",email:"",username:"",roleSelections:[]},createForm={name:"",email:"",username:"",password:"",roleSelections:[]},creatingUser=false;
  let permissionData={groups:[],memberships:[],grants:[],declaredGroups:[],selectablePermissions:[]},permissionAudit=[],permissionsLoading=false,permissionSaving="",newGroupName="",roleSearch="",editingGroup=null,groupForm={name:""},grantForm={permission:"",resourceId:"",effect:"allow"};
  let settings={registrationEnabled:true,invitationsEnabled:true,defaultRoleSelection:""},savingSettings=false,availableRoles=[],assignableRoles=[];
  let theme="dark",systemTabs=[],activeSystemTab="",systemSurface=null,systemSurfaceState={},systemSurfaceError="",systemSurfaceLoading=false;
  // Schema surfaces are an opt-in native extension. Keep the package's normal
  // view available while a newly installed package has not yet gained a native
  // renderer, instead of leaving the System screen on an unsupported message.
  const nativeSurfaceKinds=new Set(["redirect-routing","providers-catalog","session-preferences","mcp-providers","governance-defaults","auth-administration"]);
  async function request(url,options){const response=await fetch(url,options),data=await response.json();if(!response.ok||data.status>=400)throw new Error(data.message||data.error||"Request failed.");return data}
  async function load(){loading=true;error="";try{const me=await request("/auth/get");if(me.role!=="admin"){window.location.href="/";return}const data=await request("/auth/users");users=data.users||[];userPage=1;invites=data.invites||[];settings={...settings,...(data.settings||{})};availableRoles=data.availableRoles||[];assignableRoles=data.assignableRoles||availableRoles;await loadAccess()}catch(err){error=err.message||"Could not load system access."}finally{loading=false}}
  async function loadAccess(){permissionsLoading=true;try{const [overview,audit]=await Promise.all([request("/auth/permissions"),request("/auth/permissions/audit?limit=30")]);permissionData={groups:overview.groups||[],memberships:overview.memberships||[],grants:overview.grants||[],declaredGroups:overview.declaredGroups||[],selectablePermissions:overview.selectablePermissions||[]};permissionAudit=audit.entries||[]}catch(err){error=err.message}finally{permissionsLoading=false}}
  function groupsFor(userId){const ids=permissionData.memberships.filter(x=>x.userId===userId).map(x=>x.groupId);return permissionData.groups.filter(x=>ids.includes(x.id))} function membershipFor(userId,groupId){return permissionData.memberships.find(x=>x.userId===userId&&x.groupId===groupId)} function groupMembers(id){return permissionData.memberships.filter(x=>x.groupId===id)} function groupGrants(id){return permissionData.grants.filter(x=>x.subjectType==="group"&&x.subjectId===id)} function grantsFor(id){return permissionData.grants.filter(x=>x.subjectType==="user"&&x.subjectId===id)}
  function roleOptions(roles=tab==="settings"?availableRoles:assignableRoles){const saved=permissionData.groups.map(x=>({value:`group:${x.id}`,label:x.name}));const declared=roles.filter(role=>!permissionData.groups.some(group=>group.declaredPackage===role.packageName&&group.declaredGroup===role.id)).map(role=>({value:`declared:${role.packageName}:${role.id}`,label:`${role.packageLabel} · ${role.label}`}));return [...saved,...declared]} function rolesSummary(user){const names=groupsFor(user.id).map(x=>x.name);return names.length?names.join(", "):"No roles"} function visibleRoles(){const query=roleSearch.trim().toLowerCase();return permissionData.groups.filter(x=>!x.declaredPackage&&(!query||x.name.toLowerCase().includes(query)))} function permissionSummary(id){const names=groupGrants(id).map(x=>x.permission);return names.length?names.slice(0,2).join(", ")+(names.length>2?` +${names.length-2}`:""):"No permissions assigned"} function permissionsByApplication(){return permissionData.selectablePermissions.reduce((out,x)=>{(out[x.packageName]||=[]).push(x);return out},{})} function rolesByApplication(){return permissionData.declaredGroups.reduce((out,x)=>{const key=x.packageLabel||x.packageName;(out[key]||=[]).push(x);return out},{})}
  async function openEdit(user){await loadAccess();editing=user;editForm={name:user.name||"",email:user.email||"",username:user.username||"",roleSelections:groupsFor(user.id).map(x=>`group:${x.id}`)}} async function saveUser(){savingUser=true;try{await request("/auth/update-user",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({userId:editing.id,...editForm})});editing=null;await load()}catch(err){error=err.message}finally{savingUser=false}} async function createUser(){creatingUser=true;try{await request("/auth/create-account",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(createForm)});createForm={name:"",email:"",username:"",password:"",roleSelections:[]};showCreateUser=false;await load()}catch(err){error=err.message}finally{creatingUser=false}}
  async function deleteUser(user){if(!await askConfirm(`Delete ${user.username||user.email}? This permanently removes their account and access.`,{danger:true}))return;deletingUserId=user.id;try{await request("/auth/delete-user",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({userId:user.id})});await load()}catch(err){error=err.message}finally{deletingUserId=""}} async function saveSettings(){savingSettings=true;try{settings=(await request("/auth/settings",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(settings)})).settings}catch(err){error=err.message}finally{savingSettings=false}}
  async function createGroup(){const name=newGroupName.trim();if(!name)return;permissionSaving="new-group";try{const group=await request("/auth/permissions/groups",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({name})});newGroupName="";await loadAccess();openGroup(permissionData.groups.find(x=>x.id===group.id)||group)}catch(err){error=err.message}finally{permissionSaving=""}} function openGroup(group){editingGroup=group;groupForm={name:group.name};grantForm={permission:"",resourceId:"",effect:"allow"}} async function updateGroup(){permissionSaving="update-group";try{await request("/auth/permissions/groups/update",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editingGroup.id,name:groupForm.name})});await loadAccess();editingGroup=permissionData.groups.find(x=>x.id===editingGroup.id)||null}catch(err){error=err.message}finally{permissionSaving=""}}
  async function deleteGroup(group){if(!await askConfirm(`Delete ${group.name}? Its members and role permissions will be removed.`,{danger:true}))return;permissionSaving=`delete-group:${group.id}`;try{await request("/auth/permissions/groups/delete",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:group.id})});if(editingGroup?.id===group.id)editingGroup=null;await loadAccess()}catch(err){error=err.message}finally{permissionSaving=""}} async function removeMembership(membership){if(!membership||!await askConfirm("Remove this role assignment?",{danger:true}))return;try{await request("/auth/permissions/memberships/delete",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:membership.id})});await loadAccess()}catch(err){error=err.message}} async function toggleMember(group,user){const membership=membershipFor(user.id,group.id);if(membership)return removeMembership(membership);try{await request("/auth/permissions/memberships",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({userId:user.id,groupId:group.id})});await loadAccess()}catch(err){error=err.message}}
  async function addGrant(subjectType,subjectId){if(!grantForm.permission)return;permissionSaving="grant";try{const fullPackage=grantForm.permission.match(/^full:(.+)$/)?.[1];const url=fullPackage?"/auth/permissions/grants/full-package":"/auth/permissions/grants";const body=fullPackage?{subjectType,subjectId,packageName:fullPackage,effect:grantForm.effect}:{subjectType,subjectId,...grantForm};await request(url,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});grantForm={permission:"",resourceId:"",effect:"allow"};await loadAccess()}catch(err){error=err.message}finally{permissionSaving=""}} async function removeGrant(grant){try{await request("/auth/permissions/grants/delete",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:grant.id})});await loadAccess()}catch(err){error=err.message}}
  async function createInvite(){creatingInvite=true;try{inviteCode=(await request("/auth/invite",{method:"POST"})).code;await load()}catch(err){error=err.message}finally{creatingInvite=false}} async function revokeInvite(invite){if(!await askConfirm(`Revoke invitation ${invite.code}?`,{danger:true}))return;revokingCode=invite.code;try{await request("/auth/revoke-invite",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({code:invite.code})});await load()}catch(err){error=err.message}finally{revokingCode=""}}
  async function loadSystemTabs(){try{systemTabs=(await request("/auth/system/tabs")).tabs||[]}catch(_){systemTabs=[]}} function activeTabDefinition(){return systemTabs.find(x=>x.id===activeSystemTab)} async function openSystemTab(id){activeSystemTab=id;systemSurface=null;systemSurfaceError="";const item=activeTabDefinition();if(!item||item.renderer!=="schema")return;systemSurfaceLoading=true;try{const data=await request(`/${item.packageName}/system/view`);if(nativeSurfaceKinds.has(data.surface?.kind)){systemSurface=data.surface;systemSurfaceState=data.state||{}}}catch(err){systemSurfaceError=err.message}finally{systemSurfaceLoading=false}} function readTheme(){try{theme=localStorage.getItem("agent:theme")==="light"?"light":"dark"}catch(_){}} onMount(()=>{readTheme();load();loadSystemTabs()});
</script>

<div class="wrap" data-theme={theme}><main class="content"><header class="header"><p class="eyebrow">System</p><h1>Users & access</h1><p>Manage people and their access to this Runtime.</p></header>{#if error}<div class="error" role="alert">{error}</div>{/if}<nav class="tabs" aria-label="System administration"><button class:active={tab==="users"&&!activeSystemTab} on:click={()=>{tab="users";activeSystemTab=""}}>Users</button><button class:active={tab==="access"&&!activeSystemTab} on:click={()=>{tab="access";activeSystemTab="";loadAccess()}}>Roles</button><button class:active={tab==="settings"&&!activeSystemTab} on:click={()=>{tab="settings";activeSystemTab=""}}>Settings</button>{#if settings.registrationEnabled&&settings.invitationsEnabled}<button class:active={tab==="invitations"&&!activeSystemTab} on:click={()=>{tab="invitations";activeSystemTab=""}}>Invitations</button>{/if}{#each systemTabs as item}<button class:active={activeSystemTab===item.id} on:click={()=>openSystemTab(item.id)}>{item.label}</button>{/each}</nav>
{#if loading}<p class="muted">Loading users…</p>{:else if activeSystemTab}<section class="system-extension">{#if systemSurfaceLoading}<p class="muted">Loading extension…</p>{:else if systemSurfaceError}<p class="error">{systemSurfaceError}</p>{:else if systemSurface}<SystemSurface surface={systemSurface} state={systemSurfaceState} actionUrl={`/${activeTabDefinition().packageName}/system/action`} />{:else}<iframe title={activeTabDefinition()?.label} src={`/view/${activeTabDefinition()?.packageName}/${activeTabDefinition()?.view}`}></iframe>{/if}</section>
{:else if tab==="users"}<section class="card"><header class="section-heading"><button class="primary" on:click={()=>showCreateUser=!showCreateUser}>{showCreateUser?"Close":"Add user"}</button></header>{#if showCreateUser}<form class="form" on:submit|preventDefault={createUser}><label>Name<input bind:value={createForm.name}/></label><label>Email<input type="email" bind:value={createForm.email} required/></label><label>Username<input bind:value={createForm.username} required/></label><label>Password<input type="password" bind:value={createForm.password} required/></label><label>Roles<select multiple bind:value={createForm.roleSelections}>{#each roleOptions() as role}<option value={role.value}>{role.label}</option>{/each}</select></label><div class="actions"><button class="primary" disabled={creatingUser}>Create user</button></div></form>{/if}<ul class="list">{#each pagedUsers() as user}<li><div class="user-row"><div><strong>{user.name||user.username||user.email}</strong><small>{user.email}</small></div><span class="badge">{rolesSummary(user)}</span><button on:click={()=>openEdit(user)}>Edit</button>{#if user.role!=="admin"}<button class="danger" on:click={()=>deleteUser(user)} disabled={deletingUserId===user.id}>Delete</button>{/if}</div>{#if editing?.id===user.id}<form class="form edit-form" on:submit|preventDefault={saveUser}><label>Name<input bind:value={editForm.name}/></label><label>Email<input type="email" bind:value={editForm.email} required/></label><label>Username<input bind:value={editForm.username} required/></label><label>Roles<select multiple bind:value={editForm.roleSelections}>{#each roleOptions() as role}<option value={role.value}>{role.label}</option>{/each}</select></label><div class="actions"><button class="primary" disabled={savingUser}>Save changes</button><button type="button" on:click={()=>editing=null}>Cancel</button></div></form><section class="user-access"><h4>Roles and extra permissions</h4>{#each groupsFor(user.id) as group}<div class="access-row"><span>{group.name}</span><button on:click={()=>removeMembership(membershipFor(user.id,group.id))}>Remove role</button></div>{:else}<p class="muted">No roles assigned.</p>{/each}<details><summary>Extra permissions</summary>{#each grantsFor(user.id) as grant}<div class="access-row"><span>{grant.permission}</span><button on:click={()=>removeGrant(grant)}>Remove</button></div>{/each}<div class="compose"><select aria-label="Permission" bind:value={grantForm.permission}><option value="" disabled>Select permission</option>{#each Object.entries(permissionsByApplication()) as [app,permissions]}<optgroup label={app}><option value={`full:${app}`}>Full Access</option>{#each permissions as permission}<option value={permission.permission}>{permission.resource} · {permission.action}</option>{/each}</optgroup>{/each}</select><button on:click={()=>addGrant("user",user.id)}>Add permission</button></div></details></section>{/if}</li>{/each}</ul><footer class="pagination"><span class="muted">{users.length} account{users.length===1?"":"s"} total</span>{#if userPageCount()>1}<div class="pagination-controls"><button aria-label="Previous page" on:click={()=>setUserPage(userPage-1)} disabled={userPage===1}>Previous</button><span class="muted">Page {userPage} of {userPageCount()}</span><button aria-label="Next page" on:click={()=>setUserPage(userPage+1)} disabled={userPage===userPageCount()}>Next</button></div>{/if}</footer></section>
{:else if tab==="settings"}<section class="card settings"><h2>Registration</h2><form on:submit|preventDefault={saveSettings}><label class="switch-row"><span><strong>Allow registration</strong><small>Anyone can create a new account from the sign-in page.</small></span><input type="checkbox" bind:checked={settings.registrationEnabled}/></label>{#if settings.registrationEnabled}<label class="switch-row"><span><strong>Enable invitations</strong><small>Show invitation codes on sign-up and add the Invitations tab.</small></span><input type="checkbox" bind:checked={settings.invitationsEnabled}/></label><label class="field-row"><span><strong>Default role</strong><small>Automatically assign one role to new registrations.</small></span><select aria-label="Default role for new registrations" bind:value={settings.defaultRoleSelection}><option value="">No default role</option>{#each roleOptions() as role}<option value={role.value}>{role.label}</option>{/each}</select></label>{/if}<div class="actions"><button class="primary" disabled={savingSettings}>Save settings</button></div></form></section>
{:else if tab==="invitations"}<section class="card"><header class="section-heading"><h2>Invitations</h2><button class="primary" on:click={createInvite} disabled={creatingInvite}>Create invitation</button></header>{#if inviteCode}<p class="notice">New invitation code: <code>{inviteCode}</code></p>{/if}<ul class="list">{#each invites as invite}<li class="invite-row"><code>{invite.code}</code><span class="badge">{invite.consumed?"Used":invite.revoked?"Revoked":"Available"}</span>{#if !invite.consumed&&!invite.revoked}<button class="danger" on:click={()=>revokeInvite(invite)} disabled={revokingCode===invite.code}>Revoke</button>{/if}</li>{/each}</ul></section>
{:else if tab==="access"}<section class="access" aria-label="Role management"><header class="role-intro"><h2>Roles</h2><form class="role-create" on:submit|preventDefault={createGroup}><input aria-label="New role name" bind:value={newGroupName} placeholder="New role name"/><button class="primary" disabled={permissionSaving==="new-group"}>Create role</button></form></header>{#if permissionsLoading}<p class="muted">Loading…</p>{:else}<div class="role-toolbar"><input aria-label="Search roles" bind:value={roleSearch} placeholder="Search roles"/><span class="muted">{visibleRoles().length}</span></div><div class="role-layout"><section class="role-list" aria-label="Custom roles">{#each visibleRoles() as group}<button class:active-role={editingGroup?.id===group.id} class="role-card" on:click={()=>openGroup(group)}><span><strong>{group.name}</strong><small>{permissionSummary(group.id)}</small></span><span class="role-counts">{groupMembers(group.id).length} people<br/>{groupGrants(group.id).length} permissions</span></button>{:else}<p class="muted empty-roles">No roles yet.</p>{/each}</section><aside class="role-editor">{#if editingGroup}<header class="section-heading"><h3>{editingGroup.name}</h3><button on:click={()=>editingGroup=null}>Close</button></header><form class="rename-role" on:submit|preventDefault={updateGroup}><label>Name<input bind:value={groupForm.name} required/></label><button class="primary" disabled={permissionSaving==="update-group"}>Save</button></form><section><h4>Permissions</h4>{#each groupGrants(editingGroup.id) as grant}<div class="access-row"><span>{grant.permission}</span><button on:click={()=>removeGrant(grant)}>Remove</button></div>{:else}<p class="muted">None</p>{/each}<details><summary>Add permission</summary><div class="compose"><select aria-label="Role permission" bind:value={grantForm.permission}><option value="" disabled>Select permission</option>{#each Object.entries(permissionsByApplication()) as [app,permissions]}<optgroup label={app}><option value={`full:${app}`}>Full Access</option>{#each permissions as permission}<option value={permission.permission}>{permission.resource} · {permission.action}</option>{/each}</optgroup>{/each}</select><select aria-label="Role permission effect" bind:value={grantForm.effect}><option value="allow">Allow</option><option value="deny">Deny</option></select><button on:click={()=>addGrant("group",editingGroup.id)} disabled={!grantForm.permission}>Add</button></div></details></section><section><h4>People <small>{groupMembers(editingGroup.id).length}</small></h4><details><summary>Manage</summary>{#each users as user}<label class="check-row"><input type="checkbox" checked={!!membershipFor(user.id,editingGroup.id)} on:change={()=>toggleMember(editingGroup,user)}/><span>{user.name||user.username||user.email}<small>{user.email}</small></span></label>{/each}</details></section><footer class="role-danger"><button class="danger" on:click={()=>deleteGroup(editingGroup)}>Delete role</button></footer>{:else}<div class="editor-placeholder"><h3>Select a role</h3></div>{/if}</aside></div><details class="secondary-role-info"><summary>Package roles and activity</summary><section><h3>Package roles</h3>{#each Object.entries(rolesByApplication()) as [app,roles]}<div class="role-set"><h4>{app}</h4>{#each roles as role}<div class="access-row"><span>{role.label}</span><small>{role.permissions.join(", ")}</small></div>{/each}</div>{:else}<p class="muted">None</p>{/each}</section><section class="audit"><h3>Recent activity</h3>{#each permissionAudit as entry}<div><span>{entry.action}</span><small>{entry.createdAt?new Date(entry.createdAt).toLocaleString():""}</small></div>{:else}<p class="muted">None</p>{/each}</section></details>{/if}</section>{/if}</main></div><Dialogs/>
<style>:global(*){box-sizing:border-box}.wrap{--bg:#111;--surface:#181818;--raised:#202020;--border:rgba(255,255,255,.1);--text:#f5f5f5;--muted:#888;--accent:#f5f5f5;--danger:#ff9b9b;min-height:100dvh;background:var(--bg);color:var(--text);font-family:Ubuntu,system-ui,sans-serif}.wrap[data-theme="light"]{--bg:#fff;--surface:#f5f5f5;--raised:#ececec;--border:rgba(0,0,0,.1);--text:#1a1a1a;--muted:#666;--accent:#111;--danger:#a52222}.content{max-width:960px;margin:auto;padding:3.5rem 1.5rem}h1,h2,h3,h4,p{margin:0}h1{font-size:2.25rem;letter-spacing:-.04em}h2{font-size:1.2rem}h3{font-size:1rem}.header{margin-bottom:2rem}.muted,small,.header p:last-child{color:var(--muted)}.eyebrow{color:var(--muted);font-size:.72rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;margin-bottom:.45rem}.tabs{display:flex;gap:.35rem;border-bottom:1px solid var(--border);margin-bottom:1.5rem;overflow:auto}button{background:var(--raised);border:1px solid var(--border);border-radius:8px;color:var(--text);cursor:pointer;padding:.55rem .8rem}button:hover{opacity:.82}button.active,button.primary{background:var(--accent);border-color:var(--accent);color:var(--bg)}button.danger{color:var(--danger)}button:disabled{opacity:.55}.tabs button{border-radius:8px 8px 0 0;border-bottom:0;white-space:nowrap}.card,.access,.system-extension{background:var(--surface);border:1px solid var(--border);border-radius:14px;padding:1.35rem}.section-heading,.user-row,.invite-row,.access-row,.audit div{align-items:center;display:flex;gap:.75rem;justify-content:space-between}.list{list-style:none;margin:1rem 0 0;padding:0}.list>li{border-top:1px solid var(--border);padding:.9rem 0}.pagination{align-items:center;border-top:1px solid var(--border);display:flex;gap:1rem;justify-content:space-between;margin-top:1rem;padding-top:1rem}.pagination-controls{align-items:center;display:flex;gap:.5rem}.user-row>div{margin-right:auto}.user-row small,.check-row small{display:block;margin-top:.2rem}.badge{background:var(--raised);border-radius:999px;color:var(--muted);font-size:.75rem;padding:.24rem .55rem}.form{display:grid;gap:.8rem;grid-template-columns:repeat(2,minmax(0,1fr));margin-top:1rem;max-width:680px}.edit-form,.user-access{border-top:1px solid var(--border);margin-top:1rem;padding-top:1rem}label{display:grid;font-size:.85rem;gap:.35rem}input,select{background:var(--bg);border:1px solid var(--border);border-radius:8px;color:var(--text);padding:.6rem;width:100%}.actions,.compose{display:flex;gap:.5rem}.actions{grid-column:1/-1}.error,.notice{border-radius:8px;margin:1rem 0;padding:.75rem}.error{background:#442020;color:#ffd4d4}.notice{background:var(--raised)}.switch-row,.field-row{align-items:center;border-top:1px solid var(--border);display:flex;gap:1rem;justify-content:space-between;padding:1rem 0}.field-row select{max-width:22rem}.switch-row input,.check-row input{height:1.2rem;width:1.2rem}details{margin-top:1rem}summary{cursor:pointer}.access-row{border-bottom:1px solid var(--border);padding:.55rem 0}.role-intro{align-items:end;display:flex;gap:1.5rem;justify-content:space-between}.role-intro>div{max-width:570px}.role-intro .muted{margin-top:.45rem}.role-create{display:flex;gap:.5rem;min-width:300px}.role-toolbar{align-items:center;border-top:1px solid var(--border);display:flex;gap:1rem;justify-content:space-between;margin-top:1.25rem;padding-top:1rem}.role-toolbar input{max-width:280px}.role-layout{display:grid;gap:1rem;grid-template-columns:minmax(220px,.78fr) minmax(0,1.22fr);margin-top:1rem}.role-list{display:grid;align-content:start;gap:.5rem}.role-card{align-items:center;background:transparent;display:flex;justify-content:space-between;padding:.8rem;text-align:left;width:100%}.role-card strong,.role-card small{display:block}.role-card small{margin-top:.25rem;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.role-card.active-role{background:var(--raised);border-color:var(--text)}.role-counts{color:var(--muted);font-size:.75rem;line-height:1.45rem;text-align:right;white-space:nowrap}.role-editor{border:1px solid var(--border);border-radius:10px;min-height:370px;padding:1rem}.role-editor section{border-top:1px solid var(--border);margin-top:1rem;padding-top:1rem}.rename-role{align-items:end;display:flex;gap:.5rem;margin-top:1rem}.rename-role label{flex:1}.editor-placeholder{display:grid;min-height:330px;place-content:center;text-align:center}.editor-placeholder p{margin-top:.4rem}.role-danger{border-top:1px solid var(--border);margin-top:1rem;padding-top:1rem}.secondary-role-info{border-top:1px solid var(--border);margin-top:1.25rem;padding-top:1rem}.secondary-role-info section{border-top:1px solid var(--border);margin-top:1rem;padding-top:1rem}.role-set{margin-top:.8rem}.audit div{border-top:1px solid var(--border);padding:.45rem 0}.check-row{align-items:center;border-top:1px solid var(--border);display:flex;gap:.65rem;padding:.55rem 0}.empty-roles{padding:.8rem}.system-extension{min-height:680px;padding:0;overflow:hidden}.system-extension iframe{border:0;display:block;height:76dvh;width:100%}@media(max-width:680px){.content{padding:2rem 1rem}.form,.role-layout{grid-template-columns:1fr}.user-row,.field-row,.role-intro,.pagination{align-items:flex-start;flex-wrap:wrap}.pagination-controls{width:100%;justify-content:space-between}.field-row select{max-width:none}.role-create,.compose,.rename-role{flex-direction:column;width:100%}.role-create{min-width:0}.role-toolbar{align-items:stretch;flex-direction:column}.role-toolbar input{max-width:none}}</style>
